import{_ as s,C as a,o as n,c as l,j as t,a as o,E as d,ag as c}from"./chunks/framework.HG0H2VLS.js";const x=JSON.parse('{"title":"FilterDropdowns","description":"","frontmatter":{},"headers":[],"relativePath":"patterns/filter-dropdowns.md","filePath":"patterns/filter-dropdowns.md"}'),h={name:"patterns/filter-dropdowns.md"},p={id:"filterdropdowns",tabindex:"-1"};function u(m,e,g,w,b,f){const r=a("Badge"),i=a("ComponentDemo");return n(),l("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-filterdropdowns",tabindex:"-1"},[o("title: FilterDropdowns "),t("a",{class:"header-anchor",href:"#title-filterdropdowns","aria-label":'Permalink to "title: FilterDropdowns"'},"​")],-1)),t("h1",p,[e[0]||(e[0]=o("FilterDropdowns ",-1)),d(r,{type:"info",text:"Design System"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#filterdropdowns","aria-label":'Permalink to "FilterDropdowns <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,"filter popover bodies (320px card + Apply)")],-1)),d(i,{src:"/demos/src/patterns/FilterDropdowns/FilterDropdowns.html"}),e[6]||(e[6]=c('<h2 id="dependencies-composed" tabindex="-1">Dependencies (composed) <a class="header-anchor" href="#dependencies-composed" aria-label="Permalink to &quot;Dependencies (composed)&quot;">​</a></h2><ul><li><strong>Input</strong> (<code>78:2016</code>) — the &quot;Filter by X&quot; header label, and the select / search / date-operator fields (label + field + right icon).</li><li><strong>Checkbox</strong> (<code>2043:2985</code>) — Multi Select rows and the single Checkbox type.</li><li><strong>FilterDropdownItemGroup</strong> (<code>3032:18397</code>) + <strong>FilterDropdownItem</strong> (<code>3032:18152</code>) — the Select Options lists.</li><li><strong>FilterItem</strong> (<code>2972:1058</code>) — the empty/dashed chips in More Filters.</li><li><strong>DatePicker</strong> (<code>3039:8761</code>) — the date operand fields (Date Range / Date Equal To), as popover triggers.</li><li><strong>Button</strong> (<code>53:2489</code>) — the primary Apply button (full-width).</li></ul><h2 id="variant-matrix-17-type-values" tabindex="-1">Variant matrix (17 Type values) <a class="header-anchor" href="#variant-matrix-17-type-values" aria-label="Permalink to &quot;Variant matrix (17 Type values)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Node ID</th><th>Type</th><th>Body composition</th><th>Built</th></tr></thead><tbody><tr><td>3039:5627</td><td>Select</td><td><em>consolidated</em> → shown as Select Options (see below)</td><td>🔁</td></tr><tr><td>3039:5632</td><td>w/Placeholder</td><td><em>consolidated</em> → shown as Select Options (see below)</td><td>🔁</td></tr><tr><td>3039:5633</td><td>Text</td><td>Input (text)</td><td>✅</td></tr><tr><td>3039:5626</td><td>Checkbox</td><td>title + single Checkbox</td><td>✅</td></tr><tr><td>3039:5629</td><td>Multi Select</td><td>label + Checkbox list (gap-5, max-h 384px)</td><td>✅</td></tr><tr><td>3039:5623</td><td>Multi Select w/search</td><td>Input (search) + scrolling Checkbox list</td><td>✅</td></tr><tr><td>3039:5634</td><td>Select Options</td><td>Input (chevron) + FilterDropdownItemGroup + Apply (open state)</td><td>✅</td></tr><tr><td>3039:5628</td><td>Select Options w/subtext</td><td>Input (chevron) + FilterDropdownItemGroup (subtext) + Apply</td><td>✅</td></tr><tr><td>3039:5636</td><td>Date In the last</td><td>Input (operator) + [number + unit select]</td><td>✅</td></tr><tr><td>3039:5635</td><td>Date Range</td><td>Input (operator) + [DatePicker &quot;and&quot; DatePicker]</td><td>✅</td></tr><tr><td>3039:5631</td><td>Date Equal To</td><td>Input (operator) + corner + DatePicker</td><td>✅</td></tr><tr><td>3039:5637</td><td>More Filters</td><td>FilterItem empty/rounded chips (no Apply)</td><td>✅</td></tr><tr><td>3039:5638</td><td>Predictive Text</td><td><em>consolidated</em> → Predictive Text Options (predictive always reveals options)</td><td>🔁</td></tr><tr><td>3039:5625</td><td>Predictive Text Options</td><td>text Input + type-to-reveal single-select menu + Apply</td><td>✅</td></tr><tr><td>3039:5622</td><td>Predictive text Options w/subtext</td><td>same, with subtext rows + Apply</td><td>✅</td></tr><tr><td>3039:5624</td><td>Multi Select Table</td><td>640px card: label + FilterItem chips + Datatables (checkbox/Name/Catalogue ID/Zone, row-link) + Apply</td><td>✅</td></tr><tr><td>3039:5630</td><td>Multi Select Modal</td><td>960px Modal: title + 7 FilterItem chips + Datatables (adds Price) + Cancel/Apply</td><td>✅</td></tr></tbody></table><p><strong>Select consolidation (user direction, 2026-07-07):</strong> the plain <code>Select</code> and <code>w/Placeholder</code> variants are NOT shown as standalone panels. Per the reference, the Select is represented as <strong>two versions of its open state</strong> — the select field + the <code>FilterDropdownItemGroup</code> dropping below it, one without sub text (<code>Select Options</code>) and one with (<code>Select Options w/subtext</code>).</p><p><strong>Apply is on EVERY type but More Filters (corrected 2026-09-17).</strong> These four option types were originally built without it, on the reading that choosing an option is the action. Figma disagrees: the card is <strong>136px</strong> in every type — label (16) + gap (8) + field (40) + gap (8) + Apply (40) + padding (2×12) — and the screenshot of <code>3039:5639</code> shows the teal button on all sixteen. Only <code>More Filters</code> (3039:5637) has none, because there a chip click IS the commit.</p><p>So <strong>picking an option is not yet a filter</strong>: it closes the menu and fills the field, and Apply commits. Note what this means for layout — Figma anchors the menu 4px under the FIELD, so an open menu <strong>overlays</strong> the Apply button rather than pushing it below. The menu is therefore a child of <code>.input</code> (which carries <code>position: relative</code> in <code>--select</code>), not a sibling of it; anchoring to the card would drop the menu under the button.</p><p><strong>Predictive types (built, user direction 2026-07-07):</strong> consolidated to <strong>2</strong> — a text Input whose suggestion menu reveals <em>as characters are typed</em> (like Select on click), then single-select fills the field. <code>Predictive Text</code> (no options) is dropped since a predictive field inherently reveals options. Wired by <code>wirePredictive</code> in <code>FilterDropdowns.js</code>.</p><p><strong>Phase 2 complete (2026-07-07):</strong> Multi Select Table (composes Datatables + FilterItem + Checkbox + Button; 640px = <code>--ai-size-10</code>, Figma&#39;s 671px snapped to token per direction) and Multi Select Modal (composes the Modal pattern + Datatables + FilterItem; 960px = <code>--ai-size-12</code>). All 17 Figma types now represented (Select and Predictive Text consolidated per direction).</p><h2 id="interaction-confirmed-with-user-2026-07-07" tabindex="-1">Interaction (confirmed with user, 2026-07-07) <a class="header-anchor" href="#interaction-confirmed-with-user-2026-07-07" aria-label="Permalink to &quot;Interaction (confirmed with user, 2026-07-07)&quot;">​</a></h2><ul><li><strong>Functional, reusing child JS.</strong> Checkboxes toggle natively; Select Options items toggle via <code>FilterDropdownItem.js</code>; date fields open a <code>DatePicker</code> popover via <code>DatePicker.js</code>.</li><li>Pattern-owned glue (<code>FilterDropdowns.js</code>): live <strong>search-filtering</strong> of the checkbox list (Multi Select w/search); an <strong>Apply</strong> button that emits <code>filter-dropdowns:apply</code>; and the <strong>interactive Select</strong> — clicking the field trigger opens/closes the floating <code>FilterDropdownItemGroup</code> menu (chevron rotates). The Select Options menus are <strong>single-select</strong>: choosing an option clears the others, sets the field value, and closes the menu; clicking outside / Esc also closes. (The shared <code>FilterDropdownItem</code> component remains multi-select for the checkbox-style lists; single-select is enforced in the pattern glue for select menus only.)</li><li>The operator / unit selects (Date types) render as readonly Input-chevron fields — a real Select/menu can be wired by the consumer.</li></ul><h2 id="token-gaps-decisions" tabindex="-1">Token Gaps / Decisions <a class="header-anchor" href="#token-gaps-decisions" aria-label="Permalink to &quot;Token Gaps / Decisions&quot;">​</a></h2><ul><li><strong>No token gaps</strong> — every value maps to an existing <code>--ai-*</code> token.</li><li><strong>Radius binding quirk:</strong> Figma bound the card <code>border-radius</code> to <code>--ai-spacing-3</code> (8px). Used <code>--ai-radius-md</code> (same 8px, correct category) — consistent with FilterDropdownItem(Group).</li><li><strong>Shadow:</strong> Figma <code>light/shadow-md</code> (<code>0 3px 10px .1, 0 1px 4px .16</code>) → <code>--ai-shadow-md</code> (<code>0 2px 10px .1</code>) — the design-system&#39;s named md shadow; optical, within tolerance.</li></ul><h2 id="resetting-a-card" tabindex="-1">Resetting a card <a class="header-anchor" href="#resetting-a-card" aria-label="Permalink to &quot;Resetting a card&quot;">​</a></h2><p><code>root.resetFilterDropdown()</code> is public on every <code>[data-filter-dropdowns]</code>, like FilterItem&#39;s <code>setFilterValues</code>. A consuming bar clears the chip and the card together, and only the card knows what &quot;unset&quot; means per type: drop the selected rows, untick the checkboxes, empty the fields — <strong>and put the select field back to its placeholder</strong>, which lives in a closure, not in the markup.</p><p>FilterBar used to do this from outside and could only manage the first half. The chosen name stayed in the field, greyed by the placeholder class, so a cleared Customer filter looked like it still had a value that could not be chosen again.</p><p><strong><code>data-placeholder</code> on <code>[data-select-value]</code></strong> is what makes the restore correct. <code>wireSelect</code> previously took the placeholder from whatever the field said at init — fine when a card is always rendered empty, wrong now that one can be rendered with a value already in it (restoring a saved view), because the placeholder became that value and clearing put it straight back. The attribute is the placeholder; the text is the state.</p><h2 id="type-more-filters-is-the-one-type-that-is-not-a-fixed-320" tabindex="-1">Type=More Filters is the one type that is not a fixed 320 <a class="header-anchor" href="#type-more-filters-is-the-one-type-that-is-not-a-fixed-320" aria-label="Permalink to &quot;Type=More Filters is the one type that is not a fixed 320&quot;">​</a></h2><p><code>.filter-dropdowns--more</code> sizes to its contents between a floor and a ceiling (designer, 2026-09-18: min <code>--ai-size-6</code>, max <code>--ai-size-10</code>). Figma draws it at the shared 320px, which suits the nine facets it shows; a real screen carries far more — Orders has 47 — and at 320 they wrap into a tall narrow column that is hard to scan.</p><p><code>max-content</code> on a wrapping flex row resolves to the width the chips would take on ONE line, so the rule reads as &quot;as wide as it wants, within bounds&quot;.</p><p>The ceiling is <code>min(var(--ai-size-10), 100cqi)</code>, not a flat 640. The base panel&#39;s <code>max-width: 100%</code> cannot cap it: the panel is absolutely positioned, so its containing block is the chip it hangs off, and 100% of that is a chip&#39;s width. Measured without the cap, a 640px panel on a 378px page sat at left -345 — off screen entirely.</p><h2 id="multi-select-table-select-all-and-row-values" tabindex="-1">Multi Select Table: select-all and row values <a class="header-anchor" href="#multi-select-table-select-all-and-row-values" aria-label="Permalink to &quot;Multi Select Table: select-all and row values&quot;">​</a></h2><p>Two attributes make this type work for a consumer, added 2026-09-18 when the Listing Screen started using it:</p><ul><li><code>data-select-all</code> on the header checkbox — <code>wireSelectAll</code> ticks and unticks every row from it, and reflects partial selection back as <code>indeterminate</code>. Without it the header checkbox was decoration.</li><li><code>data-row-value=&quot;&lt;name&gt;&quot;</code> on each row checkbox — the row&#39;s checkbox has no label of its own (the name is a sibling cell), so a consuming bar has no way to read what was selected without this.</li></ul><p>The demo carries both, so the component&#39;s own gallery exercises them.</p><h2 id="multi-select-table-no-horizontal-scroll" tabindex="-1">Multi Select Table: no horizontal scroll <a class="header-anchor" href="#multi-select-table-no-horizontal-scroll" aria-label="Permalink to &quot;Multi Select Table: no horizontal scroll&quot;">​</a></h2><p>Cells WRAP in this table rather than inheriting Table.css&#39;s <code>white-space: nowrap</code>. That nowrap is right for a table that can scroll; in a 640px picker it is the wrong trade. One real catalogue name — &quot;Affino Innovation Briefing 2019 - Actionable Intelligence, Case Study and 2020 Roadmap&quot; — took the Name column to 602px and the table to 885 inside a 623 body, putting Catalogue ID and Zone off the right-hand edge behind a scrollbar. Those are the two columns that tell two similarly named items apart, which is the whole reason this type is a table.</p><p>The two predictable columns carry a preferred width (<code>--ai-size-1</code>) and Name absorbs the variation. Without that, auto layout gave the long names so much room that the codes broke mid-string — &quot;Aff9882376&quot; rendered as &quot;Aff98823 / 76&quot;, which for an operator-typed SKU reads as a different value.</p><p><code>overflow-wrap: anywhere</code> stays on the code column as a safety net: a Catalogue ID is free text and a longer one with no break opportunity would otherwise set the column&#39;s min-content width and bring the scroll back.</p><h2 id="a-card-can-contain-a-card-so-no-descendant-queries" tabindex="-1">A card can contain a card, so no descendant queries <a class="header-anchor" href="#a-card-can-contain-a-card-so-no-descendant-queries" aria-label="Permalink to &quot;A card can contain a card, so no descendant queries&quot;">​</a></h2><p>Every wiring lookup goes through <code>own()</code> / <code>ownAll()</code>, which keep only elements whose nearest <code>[data-filter-dropdowns]</code> ancestor IS this root.</p><p>The Multi Select Table&#39;s sub-filters are <code>.filter-dropdowns</code> cards in their own right, so the pattern can now contain itself — and <code>root.querySelector(&#39;[data-filter-dropdowns-apply]&#39;)</code> reached straight through one. The outer card bound its Apply to the FIRST apply button in its subtree, which was a sub-filter&#39;s. Clicking that fired an apply for the OUTER card as well: it committed an empty value to the chip and closed the whole picker, while the sub-filter appeared to work.</p><p>Two events, one click, and only the second looked wrong. The fix is at the component, not the consumer: the same trap was waiting in <code>wireSearch</code>, <code>wireSelect</code>, <code>wirePredictive</code>, <code>wireSelectAll</code> and <code>wireReset</code>, all of which used the same descendant query.</p><h2 id="multi-select-table-solid-chips-tighter-rows" tabindex="-1">Multi Select Table: solid chips, tighter rows <a class="header-anchor" href="#multi-select-table-solid-chips-tighter-rows" aria-label="Permalink to &quot;Multi Select Table: solid chips, tighter rows&quot;">​</a></h2><p>Its four sub-filter chips are the <strong>Default</strong> FilterItem — solid, like the bar&#39;s own chips. They had been built with <code>--empty</code>, which is the dashed &quot;not yet added&quot; idiom and belongs to Add Filters and the More Filters facets; these are controls that are already present. Figma 3039:5624 draws them solid, so this was a fidelity fix, not a departure (designer, 2026-09-18).</p><p>Rows use <code>--ai-leading-sm</code>, matching the listing&#39;s own table. The shared Table default is <code>leading-md</code>, which leaves a picker you are scanning for one item looking airy. Scoped here rather than changed in Table.css.</p><h2 id="multi-select-table-scrolls-rather-than-dropping-columns" tabindex="-1">Multi Select Table scrolls rather than dropping columns <a class="header-anchor" href="#multi-select-table-scrolls-rather-than-dropping-columns" aria-label="Permalink to &quot;Multi Select Table scrolls rather than dropping columns&quot;">​</a></h2><p>It used to shed Zone at 520px and Catalogue ID at 380px. That was wrong for THIS table: those two columns are how you tell two similarly named items apart, so hiding them at narrow widths removes the reason to use a table (designer, 2026-09-18). Every column is kept and the table overflows instead.</p><p>The minimum that forces that lives on the COLUMNS, not on the table. Putting 640 — the card&#39;s own width — on the table over-shot by 17px and clipped the last column on a desktop with room to spare: 640 is the card&#39;s OUTER width, and the scrolling body&#39;s inner width is 623. Summing what each column actually needs instead (32 + 192 + 128 + 128 + 32 = 512) fits comfortably at 623 and still overflows when the card is genuinely narrow.</p><p>Measured: no scroll at all down to a 620px page; 72px of scroll at 900 and 152px at 820, which are the widths where the sidebar squeezes the card to 457 and 377.</p><p>Mouse <strong>drag-to-scroll</strong> comes with it. Touch and trackpads already scroll an overflowing box; a mouse has no gesture for it and a scrollbar under a list you are reading is easy to miss. A drag never starts on an input, button, link or label, and needs 4px of travel before it counts — so a click that wobbles is still a click.</p><p>Note this is the opposite call from the LISTING&#39;s table, which drops columns rather than scrolling. The difference is what the table is for: the listing is a view of many records where the far columns are extra, and the picker is a disambiguator where they are the point.</p><h2 id="multi-select-table-type-matches-the-orders-datatable" tabindex="-1">Multi Select Table type matches the Orders datatable <a class="header-anchor" href="#multi-select-table-type-matches-the-orders-datatable" aria-label="Permalink to &quot;Multi Select Table type matches the Orders datatable&quot;">​</a></h2><p>Same tokens, same switch. Wide: <code>--ai-font-fixed-xxs</code> headers, <code>--ai-font-fixed-xs</code> cells — the Table defaults. Cramped: <code>4xs</code> and <code>2xs</code>, the same two the Orders table steps down to.</p><p>The threshold is read from <strong><code>cs-page</code></strong>, not from the card. Keyed to its own box the picker could never agree with the listing: the card is never wider than 640 and the listing switches below 767, so at a 1200px page the listing sat at 11/13 while the picker was still at 12/14 — two tables on screen at once, in different sizes. <code>cs-page</code> is the signal the listing is really responding to (its datatable is the page column less its padding), so at ~800 the two switch together.</p><p>Measured at 1900 / 1500 / 1250 / 1150 / 900 / 820: identical in both tables at every width.</p><h2 id="multi-select-table-a-date-column" tabindex="-1">Multi Select Table: a date column <a class="header-anchor" href="#multi-select-table-a-date-column" aria-label="Permalink to &quot;Multi Select Table: a date column&quot;">​</a></h2><p>Contact Lists (2026-09-18) is the second filter to use this type, with Name + Created rather than Catalogue Item&#39;s Name / Catalogue ID / Zone. Two things followed:</p><ul><li>The column classes are no longer fixed to that one table — the screen names its own per filter. <code>--date</code> joins <code>--code</code> and <code>--zone</code> at the 128px preferred width.</li><li><code>--date</code> is the one column here that keeps <code>white-space: nowrap</code>. The picker turns wrapping on for everything so no column is pushed off the edge, but a date broken over two lines reads as two values. <code>.table</code> is in the selector purely to out-specify that blanket rule, which names an element and would otherwise win.</li></ul><h2 id="css-classes" tabindex="-1">CSS Classes <a class="header-anchor" href="#css-classes" aria-label="Permalink to &quot;CSS Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma element</th><th>CSS</th></tr></thead><tbody><tr><td>Card shell</td><td><code>.filter-dropdowns</code> (<code>--list</code> = wider gap + capped scrolling body for Multi Select types)</td></tr><tr><td>Standalone header title (Checkbox type)</td><td><code>.filter-dropdowns__title</code></td></tr><tr><td>Checkbox list</td><td><code>.filter-dropdowns__checklist</code> (scrolls under <code>--list</code>)</td></tr><tr><td>Single-checkbox body</td><td><code>.filter-dropdowns__checkbox-body</code></td></tr><tr><td>Date operand row</td><td><code>.filter-dropdowns__date-row</code></td></tr><tr><td>&quot;and&quot; separator</td><td><code>.filter-dropdowns__date-sep</code></td></tr><tr><td>Leading corner icon</td><td><code>.filter-dropdowns__date-corner</code> (Lucide <code>corner-down-right</code>, 20px)</td></tr><tr><td>More Filters chip wrap</td><td><code>.filter-dropdowns__facets</code></td></tr><tr><td>Apply</td><td><code>.btn.btn--primary.filter-dropdowns__apply</code> (full width)</td></tr><tr><td>Options popover</td><td><code>.filter-dropdown-item-group</code> (child component)</td></tr></tbody></table><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th></tr></thead><tbody><tr><td>Card bg / border / radius</td><td><code>--ai-surface-primary</code> / <code>--ai-border-secondary</code> (1px) / <code>--ai-radius-md</code></td></tr><tr><td>Card padding</td><td><code>--ai-spacing-4</code> (12px)</td></tr><tr><td>Card gap</td><td><code>--ai-spacing-3</code> (8px); <code>--ai-spacing-5</code> (16px) for <code>--list</code></td></tr><tr><td>Card shadow</td><td><code>--ai-shadow-md</code> (Figma <code>light/shadow-md</code>)</td></tr><tr><td>Card width</td><td><code>--ai-size-6</code> (320px); <code>--list</code> max-height <code>--ai-size-7</code> (384px)</td></tr><tr><td>Checklist gap / bottom pad</td><td><code>--ai-spacing-4</code> / <code>--ai-spacing-3</code></td></tr><tr><td>Date corner icon</td><td><code>--ai-icon-size-md</code> (20px), <code>--ai-icon-contrast</code></td></tr><tr><td>Header title / label</td><td><code>--ai-font-title</code> semibold <code>--ai-font-fixed-xs</code> (14px)</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Icons (Lucide):</strong> <code>chevron-down</code> (select/unit fields), <code>search</code> (search field), <code>calendar</code> (date fields, via DatePicker), <code>corner-down-right</code> (indented operand rows), <code>plus</code>/<code>circle-check</code>/<code>check</code> come from FilterItem / FilterDropdownItem / Checkbox.</li><li><strong>Header = Input label:</strong> Figma composes the Input component for the &quot;Filter by X&quot; heading (label-only for Multi Select; label + field otherwise). Checkbox type uses a standalone <code>.filter-dropdowns__title</code> instead of an Input label.</li><li><strong>Width:</strong> all bodies are 320px (<code>--ai-size-6</code>) except the pending Table (671px) and Modal (960px) which will not fit this shell — they are separate layouts in phase 2.</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=3039-5639" target="_blank" rel="noreferrer">Open in Figma</a></p>',57))])}const k=s(h,[["render",u]]);export{x as __pageData,k as default};
